CREATE view  QSL_ORDER_LIST as  SELECT        dbo.STUF_DEF.NAME + N' ' + ISNULL(dbo.ORDR_LST.CUST_NO, N' ') AS kala, dbo.TCOD_VAHEDS.NAMES, dbo.ORDR_LST.MEGH, dbo.ORDR_LST.MEGHK,   dbo.ORDR_HED.DATE, dbo.ORDR_HED.MOLAH, dbo.ORDR_LST.RADIF, dbo.ORDR_LST.ID, dbo.ORDR_HED.CUST_NO, dbo.STUF_DEF.N_FANI,   dbo.ORDR_HED.SHARAYET, dbo.ORDR_HED.USER_NAME, dbo.ORDR_LST.CODE, dbo.STUF_DEF.NAME + N' ' + ISNULL(dbo.ORDR_LST.CUST_NO, N' ')   AS name, dbo.SALA_DTL.EMZA AS EMZA1, SALA_DTL_2.EMZA AS EMZA2, SALA_DTL_1.EMZA AS EMZA3, dbo.ORDR_HED.SGN1, dbo.ORDR_HED.SGN2,dbo.ORDR_HED.SGN3  FROM            dbo.STUF_DEF INNER JOIN  dbo.ORDR_LST ON dbo.STUF_DEF.CODE = dbo.ORDR_LST.CODE INNER JOIN  dbo.TCOD_VAHEDS ON dbo.ORDR_LST.VAHED_K = dbo.TCOD_VAHEDS.CODE INNER JOIN  dbo.ORDR_HED ON dbo.ORDR_LST.ID = dbo.ORDR_HED.id LEFT OUTER JOIN  dbo.SALA_DTL AS SALA_DTL_1 ON dbo.ORDR_HED.sgn3usid = SALA_DTL_1.IDD LEFT OUTER JOIN  dbo.SALA_DTL AS SALA_DTL_2 ON dbo.ORDR_HED.sgn2usid = SALA_DTL_2.IDD LEFT OUTER JOIN  dbo.SALA_DTL ON dbo.ORDR_HED.sgn1usid = dbo.SALA_DTL.IDD
